    correct: 1,
    explanation: "## Putting Names on Life\n\nImagine walking into a library where every book has no title and no shelf label. Finding anything would be chaos. Living things face the same problem without a naming system.\n\n**Taxonomy** is the science of **naming and classifying** organisms — describing them, giving them stable names, and sorting them into groups.\n\nThe word comes from Greek *taxis* (arrangement) and *nomos* (law). It is not the same as ecology or genetics; it is the system that makes those fields talk about the same species.\n\nWhenever you see a scientific name or a family label, remember: taxonomy is what made that shared language possible.",
