    explanation: "## Three Neighbours, Three Jobs\n\nStudents often treat taxonomy, systematics, and phylogenetics as synonyms. They are related, not identical.\n\n**Taxonomy** names and classifies. **Systematics** organises diversity into a framework that reflects relationships. **Phylogenetics** reconstructs evolutionary trees from evidence.\n\nYou can classify without drawing a tree, and you can build a tree without publishing a formal name. The three tools work best together.\n\nWhenever an exam asks which field “names species,” the answer is taxonomy — not the tree-building step alone.",
