    explanation: "## One Word for Any Named Group\n\nPeople say “species” and “family” as if those were the only kinds of groups. Taxonomy needs a general word.\n\nA **taxon** (plural **taxa**) is any **named group at any rank** — a species, a genus, a class, even a domain.\n\n*Homo sapiens* is a taxon. So is Mammalia. So is Eukaryota. Rank tells you the level; taxon tells you it is a named unit.\n\nWhenever you see “this taxon,” ask “at which rank?” — the word alone does not tell you the level.",
