    correct: 1,
    explanation: "## Where the BSC Struggles\n\nNo species concept is perfect. The BSC has known blind spots.\n\nIt fits poorly with **fossils** (no breeding data), **asexual organisms**, and groups that hybridise widely yet remain distinct lineages.\n\nOther concepts (morphological, phylogenetic) cover some of those cases better.\n\nWhenever a question asks for a BSC limitation, fossils and asexual taxa are the classic answers.",
