    explanation: "## Mayr and the BSC\n\nThe Biological Species Concept is closely tied to the work of Ernst Mayr.\n\nMayr emphasised populations, gene flow, and isolation as the heart of the species problem in sexual organisms.\n\nHis framing dominated mid-twentieth-century thinking and still anchors many textbooks.\n\nWhenever the BSC appears in a history-of-ideas question, Mayr is the name to connect.",
