    explanation: "## The Highest Rank in Biology\n\nOnce life was shown to have three deep branches, biologists needed a name for the rank that sat above kingdom.\n\nThat rank is the **domain** — the broadest category in the modern hierarchy.\n\nThe three domains are *Bacteria*, *Archaea*, and *Eukarya*, and they sit above every kingdom on Earth.\n\nThis matters because kingdom-level thinking made biologists treat all prokaryotes as cousins. Domain-level thinking makes them separate branches — like plants and animals.\n\nWhenever you see the phrase \"three domains of life,\" remember that domain is not just a new label — it is a claim about how different those groups really are.",
