    explanation: "## A Wall That Fools Enzymes\n\nImagine a drug designed to dissolve bacterial cell walls but leave everything else untouched. That drug exists — it is called lysozyme, and it works by cutting peptidoglycan.\n\nMany archaea survive it because they build their walls from a different polymer: **pseudomurein**.\n\nThe substitution is subtle — *N-acetyltalosaminuronic acid* replaces the N-acetylmuramic acid found in bacteria — but it changes the wall shape enough that lysozyme cannot cut it.\n\nThis means a drug that kills one prokaryote often leaves the other untouched.\n\nUnderstanding this is not trivia — it explains why Archaea and Bacteria are treated as separate domains rather than one kingdom of \"prokaryotes.\"",
