    explanation: "## The Kingdom That Had to Go\n\nSome categories disappear not because they were wrong, but because they mixed things that should never have been together.\n\nThe kingdom **Monera** is the classic example. It was supposed to hold all prokaryotes — but it forced bacteria and archaea into the same box even though they are as different as plants and animals.\n\n*Monophyletic* is the term for a group that contains an ancestor and all of its descendants. Monera failed that test — it was not a natural group.\n\nWhen rRNA data proved the split, Monera had to be retired.\n\nKingdom Protista, by contrast, still survives — because although it is also not monophyletic, it remains convenient for organising simple eukaryotes in teaching.",
