    explanation: "## Why Salt Kills\n\nPut a freshwater fish in the ocean and it dies. Put a human cell in a hypersaline lake and it shrivels.\n\nThe reason is **osmosis** — water moves from where there is less solute to where there is more.\n\nIn a hypersaline lake, the outside has far more salt than the inside of a normal cell. So water rushes *out*, and the cell dehydrates.\n\nThis is the same reason salt preserves meat: the salt draws water out of bacteria, killing them before they can spoil the food.\n\nHalophiles survive only because they maintain *internal* salt levels that match the outside — the same trick that lets them live where nothing else can.",
