    explanation: "## The Only Cells That Make Methane\n\nEvery swamp, every rice paddy, and every cow gut produces the same gas: methane. And in every case, the cells making it are the same group.\n\nThe **methanogens** are the only known prokaryotes that produce methane as a metabolic byproduct.\n\n*Methanogenesis* is the chemical name for the process, and it uses hydrogen and carbon dioxide as starting materials.\n\nNo other kind of cell on Earth can do this.\n\nThis is one of the cleanest examples in biology of a metabolic pathway unique to one group. When you see the methane, you know the methanogens are responsible.",
