    explanation: "## The Unseen Recyclers\n\nWhen a tree falls in a forest, it does not simply disappear. Over months and years, its wood, leaves, and bark break down — and the elements inside return to the soil.\n\nThe organisms doing this work are prokaryotes, and they recycle **carbon, oxygen, and nitrogen**.\n\n*Biogeochemical cycles* is the technical term for these global element cycles.\n\nWithout decomposers, dead matter would pile up, and nutrients would be locked away forever.\n\nWhenever you think about ecosystems, remember that the visible plants and animals depend on invisible microbes cycling the elements they need to survive.",
