    explanation: "## The Border of the Cell\n\nEvery cell needs a boundary — a barrier that decides what comes in and what stays out. In bacteria, that boundary is the **cytoplasmic membrane**.\n\nThe problem is that bacteria do not have the organelles we take for granted in eukaryotes. There are no mitochondria, no endoplasmic reticulum, no nuclear envelope.\n\nSo the cytoplasmic membrane has to do extra work. It carries out *aerobic respiration*, ATP synthesis, and many other jobs that eukaryotes distribute among organelles.\n\nThis is why many antibiotics target the bacterial membrane — it is too essential to do without.\n\nWhenever you see a bacterial cell diagram, remember that most of what the cell does happens on this single membrane.",
