    explanation: "## The Wall That Holds the Pressure\n\nPut a bacterium in fresh water and it will swell. Water rushes in by osmosis, and without a strong wall, the cell would burst.\n\nBacteria survive because their walls are built from **peptidoglycan** — a mesh of sugar chains cross-linked by short peptides.\n\n*Peptidoglycan* is unique to bacteria. It is not found in archaea, plants, fungi, or animals.\n\nThis uniqueness is exactly why it is such a good drug target. Penicillin blocks peptidoglycan cross-linking, so the wall weakens and the cell explodes under its own internal pressure.\n\nWhenever you hear about a bacterial cell wall, remember: it is not just a shell. It is a pressure vessel that keeps the cell alive.",
