    explanation: "## One Stain That Splits Bacteria in Two\n\nIf a doctor needs to know what kind of bacterium is causing an infection, they cannot wait days for a culture. They need an answer today.\n\nThe **Gram stain** gives them that answer in minutes. It splits bacteria into two groups based on cell wall structure, and the colour tells the doctor which group is present.\n\nThe method is a *differential stain* — it uses several dyes and a decolourisation step to reveal differences between cell types.\n\nThe two groups are Gram-positive and Gram-negative, and they respond to antibiotics differently.\n\nWhenever you see a Gram stain report in a clinical setting, remember it is not just a lab technique — it is a fast triage tool that guides treatment.",
