    explanation: "## Eating Without a Mouth\n\nBacteria cannot hunt, chew, or swallow. So how do they eat?\n\nThe answer is **absorption**. Most bacteria are heterotrophs that absorb dissolved organic molecules from their environment.\n\nBut here is the problem: large molecules like starch and protein cannot cross the cell membrane. So the bacterium has to break them down first.\n\n*Saprophytic* bacteria release enzymes onto their food, digesting it externally into small molecules that can be absorbed.\n\nThis is why bacteria can eat your food even without a mouth. They digest it from the outside, then absorb the pieces. Whenever you see food spoiling, you are watching this process in action.",
