    explanation: "## The Blue-Green Misnomer\n\nWhen you see a green scum on a pond, you might call it algae. But if that scum is made of cyanobacteria, the word \"algae\" is misleading — because cyanobacteria are not eukaryotes at all.\n\nThe traditional name is **blue-green algae**, because they are blue-green in colour and look like algae under a microscope.\n\nBut the modern term *cyanobacteria* reflects their true identity: they are prokaryotes, not algae.\n\nThe colour comes from *phycocyanin*, a blue pigment that captures light for photosynthesis.\n\nWhenever you use the term \"blue-green algae,\" remember it is a historical name. The modern word is cyanobacteria, and it tells you what these organisms really are.",
