    explanation: "## Why the Name Changed\n\nBoth cyanobacteria and true algae photosynthesise, look green, and live in water. To a nineteenth-century botanist, that was enough to call them all algae.\n\nBut cyanobacteria are **prokaryotic** — they lack a membrane-bound nucleus and organelles. True algae are eukaryotic.\n\nThe distinguishing term is *prokaryotic organisation*: DNA sits in a nucleoid, not in a nucleus.\n\nThis is a case where appearance and ancestry disagree. The two groups look similar because they both photosynthesise, but they are on completely different branches of the tree of life.\n\nWhenever two organisms look alike but are placed in different domains, remember: appearance can be misleading. Shared ancestry is the real criterion.",
