    explanation: "## Storing Energy the Animal Way\n\nPlants store energy as starch. Fungi and animals store it as glycogen. And cyanobacteria? They store it as glycogen too.\n\nThe storage molecule is **glycogen** — a branched polymer of glucose. It is compact, easy to break down, and releases glucose quickly when energy is needed.\n\nThe *glycogen* strategy matters because cyanobacteria live in environments where light is unpredictable. During dark periods, they need a fast-release energy reserve.\n\nBut here is the twist: plants inherited starch, not glycogen, from their algal ancestors — showing that even within the same lineage, storage molecules can change over time.\n\nWhenever you see glycogen in a photosynthetic organism, remember that storage chemistry does not always follow photosynthesis. It follows the organism's evolutionary history.",
