    correct: 0,
    explanation: "## The Specialists in the Filament\n\nMost cells in a cyanobacterial filament photosynthesise. But if the filament needs nitrogen, it needs help from a different kind of cell.\n\nThe **heterocyst** is that specialist. It fixes atmospheric nitrogen into ammonia, a form the cell can use.\n\nThe technical term is *nitrogen fixation*, and it requires a specific enzyme called nitrogenase.\n\nHeterocysts are larger than ordinary cells and have thick walls, because they need to protect the enzyme from oxygen. Nitrogenase is destroyed by oxygen, and photosynthesis produces oxygen.\n\nThis is one of the best examples of cell differentiation in bacteria. Within a single filament, some cells specialise for photosynthesis and others for nitrogen fixation — a division of labour you usually only see in multicellular organisms.",
