    correct: 1,
    explanation: "## The Enzyme That Splits the Strongest Bond\n\nThe nitrogen molecule in the air is held together by one of the strongest bonds in chemistry. Breaking it requires a specific enzyme: **nitrogenase**.\n\nThe problem is that nitrogenase is fragile. Oxygen destroys it almost immediately, which is why nitrogen fixation cannot happen in the same cell as photosynthesis.\n\n*Oxygen sensitivity* is the reason heterocysts exist. They create a protected, oxygen-free space inside the filament where nitrogenase can work.\n\nThis enzyme is so important that life as we know it depends on it. Without nitrogenase, nitrogen would stay locked in the atmosphere forever.\n\nWhenever you think about nitrogen and life, remember: no nitrogenase, no proteins, no DNA, no life.",
