    correct: 2,
    explanation: "## A Fortress for a Fragile Enzyme\n\nNitrogenase is one of the most important enzymes on Earth. It is also one of the most fragile. A single molecule of oxygen can destroy it.\n\nSo heterocysts build a fortress. Their **thick walls** and **glycolipids** slow the diffusion of oxygen into the cell, keeping the interior nearly oxygen-free.\n\nThe technical term is *oxygen barrier* — a physical and chemical shield that protects the enzyme from the byproducts of photosynthesis happening in neighbouring cells.\n\nWithout this barrier, nitrogen fixation would be impossible in an oxygen-rich environment. Life would lose a critical source of usable nitrogen.\n\nWhenever you see a nitrogen-fixing organism, remember: it is not just the enzyme that matters, but the structure that protects it.",
