    explanation: "## Two Products from One Reaction\n\nWhen nitrogenase breaks the N₂ bond, it produces two things: **ammonia** and **hydrogen gas**.\n\nThe ammonia is what the cell actually wants — it is used to build amino acids, nucleotides, and other essential molecules.\n\nBut the hydrogen gas is released as a byproduct. This is a loss of energy for the cell, and some nitrogen-fixing organisms have evolved additional enzymes to recover it.\n\nThe next step is *ammonia assimilation*, where the cell attaches ammonia to carbon skeletons to make the building blocks of life.\n\nWhenever you study nitrogen fixation, remember: it is not a clean reaction. It produces a valuable product and an expensive side product, and the cell has to manage both.",
