    explanation: "## A Poison That Attacks the Brain\n\nWhen animals drink from a pond covered in cyanobacteria, they do not always die of liver failure. Sometimes the death is neurological — paralysis, seizures, and rapid collapse.\n\nThe cause is **anatoxin**, a neurotoxin produced by some cyanobacterial species.\n\nThe technical category is *neurotoxin* — a poison that targets nerve cells rather than other tissues. Anatoxin mimics acetylcholine, blocking nerve signals and causing paralysis.\n\nThis is why livestock deaths from cyanobacteria can be dramatic and sudden: the nervous system shuts down before other symptoms appear.\n\nWhenever you see a sudden paralysis outbreak near a pond, cyanobacterial anatoxin is one of the first suspects.",
