    correct: 1,
    explanation: "## Two Cycles, One Group of Organisms\n\nEvery living thing needs carbon and nitrogen. Cyanobacteria are central to moving both through the biosphere.\n\nThey fix carbon through photosynthesis and fix nitrogen through heterocysts. This makes them crucial for the **carbon and nitrogen cycles**.\n\nThe technical term is *biogeochemical cycling* — the movement of elements through living organisms, the atmosphere, and the soil.\n\nWithout cyanobacteria, carbon would stay locked in CO₂ and nitrogen would stay locked in N₂. Life would slowly run out of the building blocks it needs.\n\nWhenever you think about global ecology, remember: the smallest organisms often drive the largest cycles.",
