    explanation: "## The Third Kingdom\n\nFor centuries, biologists tried to fit every organism into two boxes: plant or animal. Then microscopes revealed creatures that refused to cooperate — organisms that moved like animals but photosynthesised like plants.\n\nThe problem was that no category fit them. So a third kingdom had to be created.\n\n**Ernst Haeckel** introduced the term *Protista* in 1886 for these in-between organisms.\n\nThe name means \"the very first,\" reflecting Haeckel's view that protists were early offshoots of eukaryotic life.\n\nWhenever you see an organism that refuses to fit clean categories, remember: that is exactly the problem that created the kingdom Protista.",
