    explanation: "## Harvesting Minerals from the Sea\n\nKelp grows in the ocean, so it absorbs whatever the ocean contains. Over time, it concentrates minerals that are scarce on land.\n\nThe two most abundant are **sodium and iodine**. Iodine is especially important because the human body needs it for thyroid function.\n\nThe technical term for this accumulation is *bioaccumulation*, meaning the gradual build-up of substances inside a living organism.\n\nIn regions where the soil is iodine-poor, eating kelp or using kelp-based fertiliser can prevent goitre, a swelling of the thyroid gland.\n\nWhenever you study seaweeds, remember: they are not just food. They are mineral supplements from the ocean.",
