    correct: 0,
    explanation: "## The Word Behind the Disease\n\nLong before anyone could see a virus under a microscope, people knew something invisible was making them sick. They needed a word for it.\n\nThe word they chose was *virus* — Latin for **poison** or noxious substance.\n\nThe technical term that comes from this root is *virulent*, meaning \"capable of causing disease.\" A virulent pathogen is one that produces severe illness.\n\nThe name made sense at the time: whatever caused the disease behaved like an invisible poison.\n\nWhenever you see the word virus in any scientific context, remember its origin. It describes not what the particle is, but what it does.",
