    explanation: "## The Man Who Proved Viruses Were Chemical\n\nFor decades, biologists argued about whether viruses were alive. Some thought they were tiny cells. Others thought they were something else entirely.\n\n**Wendell Stanley** ended the argument in 1933 by crystallising tobacco mosaic virus.\n\nThe technical term that made this possible was *crystallisation* — the process of forming a repeating solid structure. Only chemical compounds can crystallise; cells cannot.\n\nStanley's discovery showed that viruses are made of nucleic acid and protein, not cells.\n\nWhenever you study the history of virology, remember: Stanley did not just describe a virus. He proved what it was made of.",
