    explanation: "## Smaller Than the Light You See By\n\nA light microscope works by focusing visible light onto a specimen. But there is a limit: light waves are too wide to resolve anything smaller than about 200 nanometres.\n\nViruses are between 17 and 1000 nanometres — many of them far below that limit.\n\nThe solution is the **electron microscope**, which uses a beam of electrons instead of light. Electrons have a much shorter wavelength, so they can resolve objects thousands of times smaller.\n\nThe technical term for this resolution power is *resolving power*, and electron microscopes exceed light microscopes by a factor of over 1000.\n\nWhenever you study viruses, remember: your eyes literally cannot see them. You need an electron beam.",
