    explanation: "## A Disease That Crosses Species\n\nMost viral diseases stay within one host species. Chicken pox only affects humans. Measles only affects humans. Smallpox only affected humans.\n\nBut some viruses jump species, and **rabies** is the classic example.\n\nThe virus infects wild and domesticated animals — bats, foxes, dogs — and can spread to humans through bites.\n\nThe technical term for a disease that passes from animals to humans is *zoonosis*. Rabies is one of the most lethal zoonoses: once symptoms appear, it is nearly always fatal.\n\nWhenever you study rabies, remember: this is not a human disease that happens to infect animals. It is an animal disease that occasionally infects humans.",
