    correct: 0,
    explanation: "## The Missing Machinery\n\nImagine a factory with blueprints but no workers, no machines, and no power supply. It cannot produce anything on its own.\n\nThat is exactly what a virus is. It has the instructions for making more viruses — but none of the machinery to carry them out.\n\nViruses lack **cytoplasm** and the biosynthetic machinery that cells use to make proteins and generate energy.\n\nThe technical term for this dependency is *obligate intracellular parasite*: a particle that must enter a living cell to reproduce.\n\nWhenever you study viruses, remember: they are not weak cells. They are chemical instructions waiting for a cell to run them.",
