    correct: 1,
    explanation: "## Suspended Animation\n\nA virus on a doorknob is not alive in any usual sense. It does not eat, grow, or move. It can sit there for hours, days, or even years.\n\nOutside a host cell, a virus is **metabolically inert** — it has no active metabolism at all.\n\nThe technical term for this state is *dormancy*, meaning the particle is waiting, not living.\n\nBut the moment it contacts a suitable host cell, it activates. Its genetic programme switches on, and the particle becomes an active infection machine.\n\nWhenever you study viruses, remember: they can wait forever. But the moment they find a host, they act.",
