    correct: 2,
    explanation: "## The First Question of Viral Classification\n\nWhen a virologist encounters a new virus, the first question is not \"what does it look like?\" or \"what does it infect?\" It is \"what kind of genome does it carry?\"\n\nViruses classify primarily by **genome type**: DNA viruses, RNA viruses, and retroviruses.\n\nThe technical term for this classification approach is *genome-based taxonomy*, and it is used because the genome determines almost every other feature of the virus.\n\nA DNA virus and an RNA virus replicate in completely different ways. They use different enzymes, mutate at different rates, and respond to different drugs.\n\nWhenever you study a new virus, start with the genome. Everything else follows from that.",
