    explanation: "## The Keys That Open Host Cells\n\nA virus floating in the bloodstream cannot simply push its way into a cell. It needs to find a specific cell type and attach to it.\n\nThat attachment is done by **spikes** — glycoproteins on the viral envelope that recognise specific receptors on the host cell surface.\n\nThe technical term for this interaction is *receptor specificity*, and it explains why each virus infects only certain hosts or tissues.\n\nWithout the right receptor, the virus cannot enter. HIV cannot infect a skin cell. Influenza cannot infect a plant.\n\nWhenever you study viral infection, remember: the spikes are the keys. The host cell must have the matching lock.",
