    correct: 0,
    explanation: "## The Virus That Started Virology\n\nTobacco mosaic virus was the first virus ever discovered, and it got there because it was easy to see — even before electron microscopes existed.\n\nIts shape is **helical** — a long rod-like structure with protein subunits arranged in a spiral around the RNA.\n\nThe technical term for this arrangement is *helical symmetry*, one of the three main viral shapes.\n\nTMV's simple structure made it the ideal model for studying how viruses are built. Much of what we know about viral assembly came from studying this one virus.\n\nWhenever you study viral structure, remember: the first virus ever seen was a rod — and it is still the clearest example of helical symmetry.",
