    explanation: "## The Twenty-Sided Shell\n\nSome viruses have shapes that look almost mathematical. Adenovirus is one of them: it is a perfect **icosahedron**, a 20-sided geometric solid made of triangular faces.\n\nThe technical term for this shape is *isometric symmetry*, and it produces a roughly spherical particle with remarkable efficiency.\n\nThe icosahedron is the most efficient way to build a shell from repeating protein subunits. It encloses maximum volume using minimum material.\n\nAdenoviruses cause respiratory infections in humans, but their shape has also made them useful in gene therapy research.\n\nWhenever you study viral structure, remember: viruses solve the same engineering problem that architects do — how to build a strong shell with limited materials.",
