    explanation: "## The Virus That Looks Like a Thread\n\nMost viruses are compact — balls, rods, or blocks. Ebola is different. Under an electron microscope, Ebola appears as a long, looping **filament**.\n\nThe technical term for this shape is *filamentous morphology*, and it is so distinctive that the virus family takes its name from it: *Filoviridae*.\n\nFilamentous shape may help the virus evade the immune system by presenting a surface that antibodies have trouble binding to.\n\nEbola causes severe haemorrhagic fever in humans, with mortality rates of 50–90% if untreated.\n\nWhenever you see the word filovirus, remember: it means thread-shaped virus. The name tells you exactly what it looks like.",
