    correct: 1,
    explanation: "## Three Family Trees\n\nVirologists group every virus on Earth into three large categories based on how their genome works.\n\nThe three groups are **RNA viruses**, **DNA viruses**, and **retroviruses**.\n\nThe technical term for retroviruses is *reverse-transcribing viruses*, because they copy RNA back into DNA — the reverse of the usual direction.\n\nEach group has different replication strategies, different mutation rates, and different drug targets. HIV is a retrovirus; influenza is an RNA virus; hepatitis B is a DNA virus.\n\nWhenever you study a new virus, ask first: which of the three groups does it belong to? The answer predicts almost everything else.",
