    explanation: "## The Plant Virus Pattern\n\nMost plant viruses are not like most animal viruses. Where animal viruses tend toward DNA genomes, plant viruses are overwhelmingly **single-stranded RNA**.\n\nThe technical term for this pattern is *genome bias*, meaning a group of related organisms shares a particular genome type.\n\nThis is not random. Single-stranded RNA viruses mutate fast, adapt quickly to plant defenses, and spread efficiently through insect vectors.\n\nPlant viruses also tend to have small genomes, because a plant cell provides most of the machinery they need.\n\nWhenever you study plant virology, remember: the genome type tells you a lot about how the virus spreads and how hard it is to control.",
