    explanation: "## The Feature That Does Not Exist\n\nBiologists classify viruses by genome type, capsid shape, and host range. But one commonly assumed feature is not on the list — because it does not exist.\n\nThat feature is **cytoplasm size**. Viruses have no cytoplasm at all.\n\nThe technical term for this fact is *acellular*, meaning the organism is not made of cells.\n\nBecause viruses are not cells, they have none of the parts of cells: no cytoplasm, no ribosomes, no organelles, no membranes of their own (unless you count the stolen envelope).\n\nWhenever someone asks how viruses are classified, remember to rule out cytoplasm first. It is the trick answer that catches students who forget what a virus is.",
