    explanation: "## Outside the Tree of Life\n\nThe three domains — Bacteria, Archaea, and Eukarya — classify **cellular life**. Every organism in those domains has a cell, a metabolism, and the ability to reproduce on its own.\n\nViruses have none of these. They are **not cellular forms**, so they cannot be placed in any domain.\n\nThe technical term for this exclusion is *acellular status*, and it is why virologists use their own classification system (the ICTV system) rather than the Linnaean hierarchy.\n\nPlacing a virus in a domain would break the meaning of domain. It is a category of cells, and viruses are not cells.\n\nWhenever someone asks why viruses are not in the tree of life, remember: the tree is a tree of cells. Viruses are not cells.",
