    explanation: "## Legs That Find the Lock\n\nA bacteriophage floating near a bacterium cannot simply bump into it and inject. It needs to recognise a specific receptor on the bacterial surface, and to do that, it uses its tail fibres.\n\n**Tail fibres** are the thin protein legs at the base of the phage that bind to specific receptors on the host cell wall.\n\nThe technical term for this recognition process is *receptor binding*, and it explains why a given phage can only infect certain bacterial strains.\n\nOnce the fibres bind, the phage's sheath contracts and injects the DNA through the cell wall.\n\nWhenever you study bacteriophages, remember: the whole infection begins with the tail fibres finding the right partner.",
