    explanation: "## A Word That Means \"Eater of Bacteria\"\n\nIn 1917, a French-Canadian microbiologist named Félix d'Herelle observed something strange: a substance that could destroy bacterial cultures.\n\nHe called it *bacteriophage*, from Greek *bacterion* (bacteria) and *phagein* (to eat).\n\nThe technical term for the killing effect is *lysis*, which means the bursting of a cell.\n\nD'Herelle's name stuck because it described exactly what the virus does: it destroys the bacteria it infects.\n\nWhenever you say the word bacteriophage, remember it is a Greek description, not a taxonomic term. It means \"bacteria-eater.\"",
