    correct: 3,
    explanation: "## The Infectious Protein\n\nIf you were told that an infectious disease could be caused by a protein alone — with no DNA and no RNA — you might not believe it. But that is exactly what prions do.\n\nPrions cause **brain degenerative diseases** like Creutzfeldt-Jakob disease and BSE (mad cow disease).\n\nThe technical term for this class of disease is *transmissible spongiform encephalopathy*, named after the sponge-like holes that appear in brain tissue.\n\nPrions are misfolded proteins that force normal proteins to misfold too, spreading the damage through the brain.\n\nWhenever you study infectious agents, remember: a protein can be infectious, and the result is always lethal.",
