    correct: 0,
    explanation: "## A Chain Reaction of Misfolding\n\nA prion has no genome. It cannot reproduce itself the way a virus does. So how does it spread through the brain?\n\nThe answer is that it **converts normal proteins** into the misfolded form.\n\nThe technical term for this is *conformational change*, where the shape of a protein determines its behaviour — and that shape is contagious.\n\nA single misfolded prion protein touches a normal one, and the normal one becomes misfolded too. The chain reaction spreads, and the misfolded proteins clump together and kill neurons.\n\nWhenever you study prions, remember: they do not need a genome. Their information is in their shape, and that shape is infectious.",
