    explanation: "## The Plant-Only Pathogen\n\nViroids are tiny, naked RNA molecules — even simpler than viruses. And they infect only **plants**.\n\nThe technical term for this host range is *plant-specific pathogenicity*, meaning viroids cause disease in plants and nothing else.\n\nA classic example is potato spindle tuber viroid, which stunts potato plants and reduces yield. The viroid spreads through contaminated sap and tools.\n\nViroids cannot infect humans or animals because they depend on plant-specific replication machinery.\n\nWhenever you study infectious agents, remember: host range is determined by what the pathogen can exploit, and viroids exploit plants only.",
