    explanation: "## Why the Flu Keeps Coming Back\n\nEvery year, a new flu vaccine is needed. Why does the virus change so much?\n\nThe answer is in its genome. Influenza has a **segmented RNA** genome — eight separate RNA molecules that can be shuffled when two viruses infect the same cell.\n\nThe technical term for this reassortment is *antigenic shift*, and it is what creates new pandemic strains.\n\nAntigenic drift, by contrast, is the slow accumulation of mutations that creates seasonal flu variants.\n\nThe 1918 flu pandemic, which killed around 22 million people, was caused by an antigenic shift.\n\nWhenever you study influenza, remember: the segmented genome is what makes the virus so unpredictable.",
