    explanation: "## Two Copies of RNA\n\nHIV carries its genome as **single-stranded RNA** — but it actually carries two identical copies of that RNA inside each virion.\n\nThe technical term for this is *diploid RNA*, which is unusual for a virus and makes HIV more resilient.\n\nWhy two copies? If one copy has a mutation or error, the second copy can serve as a template for repair during reverse transcription. This helps HIV survive its own error-prone replication.\n\nThe RNA is bound to nucleocapsid proteins, which protect it and help package it into new virions.\n\nWhenever you study HIV, remember: its genome is not just RNA. It is a pair of RNA molecules with a built-in repair system.",
