    explanation: "## Why HIV Spreads Through Sex\n\nHIV is a fragile virus. It cannot survive in the air, in water, or on surfaces. But it can survive in the body fluids exchanged during sex.\n\nThe main mode of transmission is **sexual intercourse**, through contact with seminal fluid, vaginal secretions, or blood.\n\nThe technical term for this route is *sexual transmission*, one of several modes that also include needle sharing and mother-to-child transmission during birth or breastfeeding.\n\nBecause HIV is fragile, it cannot be spread by casual contact — touching, hugging, or sharing food.\n\nWhenever you study HIV, remember: the route of transmission is limited by the virus's fragility. It needs direct access to the bloodstream or mucous membranes.",
