    explanation: "## The Shift That Changes Everything\n\nEarly in HIV infection, the virus usually uses CCR5 to enter macrophages. But HIV mutates quickly, and eventually it can switch to a different coreceptor.\n\nThat new coreceptor is **CXCR4** — used on T cells.\n\nThe technical term for this change is *tropism switch*, and it usually marks the transition from chronic infection to AIDS.\n\nWhen HIV switches to CXCR4, it starts destroying CD4+ T cells at a much faster rate. The immune system collapses, and the patient becomes vulnerable to opportunistic infections.\n\nWhenever you study HIV progression, remember: the coreceptor switch is one of the most important events in the disease timeline.",
