    explanation: "## Why Macrophages Survive HIV\n\nMost viruses kill the cells they infect. HIV does something different in macrophages: it lets them live.\n\nInstead of bursting the cell, new viruses are released by **exocytosis** — the cell packages the virions into vesicles and expels them without dying.\n\nThe technical term for this non-killing release is *non-lytic exit*, and it turns macrophages into long-term reservoirs of HIV.\n\nThese cells carry the virus throughout the body and release it slowly over months or years, making the infection almost impossible to eliminate.\n\nWhenever you study HIV persistence, remember: macrophages are not just victims. They are carriers.",
