    explanation: "## The Silent Years\n\nAfter HIV infection, symptoms may appear briefly and then vanish. The person feels fine. But the virus is not gone. It is replicating quietly, damaging the immune system one cell at a time.\n\nThis period is called the **latency period**, and it typically lasts eight to ten years.\n\nThe technical term for this phase is *clinical latency*, meaning the virus is active but not causing obvious symptoms.\n\nBecause there are no symptoms, many people do not know they are infected — which is one reason HIV spreads so efficiently.\n\nWhenever you study HIV, remember: the virus does not need symptoms to spread. It only needs time.",
