    correct: 3,
    explanation: "## Why Virus-Infected Plants Are Smaller\n\nWhen a plant is infected with a virus, it does not just look different — it grows differently. Leaves may yellow, but more importantly, the whole plant is smaller than it should be.\n\nThe reason is that viruses **reduce growth** by diverting the plant's resources to making more virus.\n\nThe technical term for this effect is *stunting*, meaning the plant fails to reach its normal height and yield.\n\nA stunted crop produces less grain, fewer fruits, and lower income for farmers.\n\nWhenever you study plant viruses, remember: the damage is not just cosmetic. It affects yield, and yield affects people.",
