    explanation: "## The Hidden Catalogue\n\nWhen people think of plant diseases, they often picture fungi or bacteria. But viruses cause a huge share of the damage — and the number is surprising.\n\nAbout **2,000 plant diseases** are caused by viruses worldwide.\n\nThe technical term for this catalogue is *viral phytopathology*, the study of plant diseases caused by viruses.\n\nThese diseases affect food crops, ornamental plants, and forestry. They reduce yields, lower quality, and cost farmers billions of dollars every year.\n\nWhenever you study plant health, remember: viruses are not just a human concern. They are a global agricultural threat.",
