    correct: 2,
    explanation: "## The Only Reliable Strategy\n\nPlant viruses cannot be cured. There is no antibiotic for a virus, no spray that will clear an infected plant. So the strategy has to be prevention.\n\nThe most reliable method is **using virus-free planting material** — starting with clean seeds, cuttings, or tubers that carry no virus.\n\nThe technical term for this approach is *phytosanitary control*, which means preventing the virus from entering the crop in the first place.\n\nFarmers also control insect vectors, clean their tools, and remove infected plants.\n\nWhenever you study plant viruses, remember: the cure does not exist. The solution is to never let the virus in.",
