    explanation: "## When Crops Fail, People Go Hungry\n\nA virus that destroys 30% of a crop is not just a biological event. It is a human welfare crisis.\n\nThe main impact of viral crop loss is **reduced food security** — less food available at higher prices.\n\nThe technical term for this effect is *agricultural vulnerability*, meaning the food system becomes less able to feed the population.\n\nDeveloping countries are hit hardest because farmers cannot afford the controls, and because they often depend on a single staple crop.\n\nWhenever you study plant viruses, remember: the impact is not just measured in dollars. It is measured in meals.",
