    explanation: "## The Pandemic That Changed the World\n\nSince 1981, more than **25 million people** have died from AIDS. The disease has reshaped public health systems, economies, and societies across the world.\n\nThe technical term for a global disease outbreak of this scale is *pandemic*, meaning an epidemic that spreads across continents.\n\nHIV has hit sub-Saharan Africa hardest, where it has reduced life expectancy, orphaned millions of children, and strained health systems for decades.\n\nAntiretroviral therapy has transformed HIV from a death sentence into a manageable chronic condition — but only for those who can access it.\n\nWhenever you study HIV/AIDS, remember: the numbers are not just statistics. They are the human cost of a virus we still cannot cure.",
