    explanation: "## The Victory We Rarely Celebrate\n\nSmallpox killed more people than any other infectious disease in history. In the 20th century alone, it caused an estimated 300 million deaths.\n\nToday, it is gone. Smallpox has been **globally eradicated** — the last natural case occurred in 1977.\n\nThe technical term for this achievement is *eradication*, meaning the permanent elimination of a disease from the wild.\n\nOnly one other disease has ever been eradicated: rinderpest, a cattle disease. Smallpox remains the only human viral disease to be wiped out.\n\nWhenever you study infectious disease, remember: eradication is possible. It happened once, and it can happen again.",
