    explanation: "## The Animals Without Backbones\n\nPick up any animal you know — a fish, a bird, a dog — and run your finger down its back. You will feel a bony ridge: the spine. That structure defines most of the animals we picture.\n\nBut the vast majority of animal species on Earth have no spine at all. These are the **invertebrates** — animals that **lack a vertebral column**.\n\nThe technical term for the backbone is *vertebral column*, a flexible bony rod that runs along the body axis and provides skeletal support.\n\nInvertebrates include worms, insects, molluscs, arachnids, and many other groups. They make up roughly 95% of all known animal species.\n\nWhenever you study animals, remember: the backboned animals you picture are the exception, not the rule.",
