    correct: 1,
    explanation: "## Three Kinds of Segmented Worms\n\nDig in a garden and you will find earthworms. Wade in a stream and you might encounter leeches. Walk on a beach and you may see bristle worms in the sand.\n\nAll three belong to Phylum Annelida, and each represents a different class.\n\nThe three classes are **Polychaeta** (bristle worms), **Oligochaeta** (earthworms), and **Hirudinea** (leeches).\n\nThe technical term that unites them all is *segmentation* — the body is built from repeating ring-like segments, inside and out.\n\nWhenever you see a worm with visible rings and a segmented body, remember: it is almost certainly an annelid.",
