    correct: 2,
    explanation: "## Legs That Look Like Paddles\n\nIf you watch a polychaete worm swimming in seawater, you will see small flaps along its sides moving rhythmically — like tiny oars pushing the worm forward.\n\nThose flaps are **parapodia** — paddle-like bristle structures on each segment of the worm.\n\nThe technical term comes from Greek: *para* (beside) and *podos* (foot). Each parapodium is a fleshy projection supported by bristles called *setae*.\n\nPolychaetes use parapodia for swimming, crawling, and sometimes for gas exchange.\n\nWhenever you see a bristle worm with paddle-like legs, remember: those are parapodia, and they are the reason the worm can move so freely in water.",
