    correct: 3,
    explanation: "## Crawling in Waves\n\nAn earthworm does not have legs, yet it moves through soil with remarkable efficiency. Watch one closely and you will see waves of contraction moving along its body.\n\nThose waves are produced by **alternating contractions** of two muscle layers: circular muscles and longitudinal muscles.\n\nThe technical term for this movement pattern is *peristalsis*, the same process that moves food through your gut.\n\nWhen the circular muscles contract, the segment lengthens. When the longitudinal muscles contract, it shortens. The sequence drives the worm forward.\n\nWhenever you study annelid movement, remember: the worm is not pushing itself forward. It is passing waves of contraction along its own body.",
