    correct: 1,
    explanation: "## Flat Like a Leaf\n\nMost animals have a body that is roughly cylindrical or spherical. Flatworms do not. They are thin — like a leaf pressed between two pieces of paper.\n\nTheir bodies are **dorsiventrally flattened**, meaning they are flattened from top to bottom.\n\nThe technical term comes from Latin: *dorsum* (back) and *venter* (belly). The flattening is so distinctive that it gives the phylum its name.\n\nWhy does this matter? A flat body gives every cell access to the outside environment — oxygen and nutrients can diffuse in without a circulatory system.\n\nWhenever you see a worm that looks like a flat ribbon or leaf, remember: it belongs to Platyhelminthes.",
