    explanation: "## Both Sexes in One Body\n\nMost animals come in two sexes. A flatworm does not. Every individual carries both male and female reproductive organs.\n\nSuch organisms are called **hermaphrodites**.\n\nThe technical term for this is *simultaneous hermaphroditism*, meaning both sets of organs are functional at the same time.\n\nWhy is this useful? A parasite living alone inside a host does not have to find a mate. Any two flatworms that meet can exchange sperm.\n\nWhenever you study parasites, remember: hermaphroditism is a common adaptation for life in isolated environments.",
