    explanation: "## The Largest Group of Animals\n\nIf you collected every animal species on Earth and counted them by group, one phylum would dominate. That phylum is Arthropoda.\n\nIt contains over a million described species — more than all other animal phyla combined.\n\nThe technical term for this dominance is *species richness*, and it reflects how successful arthropods have been in nearly every environment.\n\nThe name *Arthropoda* comes from Greek: *arthron* (joint) and *podos* (foot). Jointed legs are the defining feature.\n\nWhenever you study animal diversity, remember: the majority of animal species on Earth are arthropods. You are the minority.",
