    explanation: "## Armour That Doubles as a Skeleton\n\nArthropods do not have bones inside their bodies. Instead, they have a hard outer shell — an exoskeleton — that protects them and gives their muscles something to pull against.\n\nThat exoskeleton is made of **chitin** — a tough nitrogen-containing polysaccharide.\n\nThe technical term for this material is *chitin*, and it is also found in fungal cell walls.\n\nIn some arthropods, especially crustaceans, the exoskeleton is hardened further with calcium carbonate, making it even stronger.\n\nWhenever you study arthropods, remember: the exoskeleton is not just armour. It is their skeleton — the structure that makes movement possible.",
