    explanation: "## Eight Legs, Not Six\n\nInsects have six legs. Spiders have eight. That difference is one of the easiest ways to tell these two groups apart.\n\nArachnids — spiders, scorpions, ticks, and mites — have **four pairs of legs**, making eight legs total.\n\nThe technical term for this class is *Arachnida*, and their body is divided into two parts: the cephalothorax and the abdomen.\n\nUnlike insects, arachnids never have wings or antennae. Their first pair of appendages are chelicerae, used for feeding.\n\nWhenever you count legs, remember: six means insect, eight means arachnid. That simple rule separates the two largest classes of arthropods.",
