    explanation: "## The Barrier That Saves Coastlines\n\nWaves crash against the shore. Storms surge inland. Without a barrier, coastal villages and beaches would be washed away.\n\nCoral reefs are that barrier. They **protect shorelines from tides and currents**, absorbing wave energy before it reaches land.\n\nThe technical term for this service is *coastal defence*, and it is one of the most valuable ecosystem services provided by reefs.\n\nBeyond protection, reefs also support fisheries and tourism, providing income for millions of people.\n\nWhenever you study marine ecosystems, remember: coral reefs are not just beautiful. They are protective infrastructure that also happens to be alive.",
