    correct: 3,
    explanation: "## Three Regions, Three Jobs\n\nEvery insect, from a flea to a butterfly, is built on the same basic plan: **head, thorax, and abdomen**.\n\nThe technical term for these body regions is *tagmata*, and each one has its own set of tasks.\n\nThe head carries the sensory organs and mouthparts. The thorax carries the legs and wings. The abdomen holds the digestive and reproductive organs.\n\nThis division of labour is one reason insects can do so many things with the same starting blueprint.\n\nWhenever you study insect anatomy, start with the three regions. Everything else — every leg, every antenna, every mouthpart — is a variation on this basic plan.",
