    explanation: "## The Armour That Doubles as a Skeleton\n\nInsects do not have bones inside their bodies. Instead, they have a hard outer shell that does the same job as a skeleton — protecting their organs and giving muscles something to pull against.\n\nThat shell is called the **exoskeleton**, and it is made of **chitin** — a tough nitrogen-containing polysaccharide.\n\nThe technical term for this outer covering is *exoskeleton*, and its non-cellular outer layer is called the cuticle.\n\nIn some insects the exoskeleton is further hardened by minerals and proteins, making it rigid and protective.\n\nWhenever you study insects, remember: the skeleton is on the outside. That is what makes them so distinctive and so resistant to damage.",
