    correct: 1,
    explanation: "## Growing Inside a Shell\n\nAn insect's exoskeleton is strong — so strong that it cannot stretch. But the insect inside wants to grow. This creates a problem: how do you get bigger when your skin cannot expand?\n\nThe answer is **moulting** — the shedding of the old exoskeleton so a new, larger one can form.\n\nThe technical term for moulting is *ecdysis*, and it happens in stages: the insect swells, splits the old cuticle, crawls out, and hardens a new one.\n\nDuring the hours after moulting, the insect is soft and vulnerable — easy prey for predators.\n\nWhenever you study insect growth, remember: every time an insect gets bigger, it has to shed its skin. Growth is dangerous.",
