    correct: 2,
    explanation: "## The Hormone That Triggers Change\n\nMoulting does not happen by accident. It is triggered by a specific chemical signal — a hormone produced in the thorax.\n\nThat hormone is **ecdysone**, and it is secreted by a pair of thoracic glands.\n\nThe technical term for this class of hormone is *ecdysteroid*, and it initiates the entire sequence of moulting: separating the old cuticle, producing a new one, and hardening it.\n\nWithout ecdysone, an insect would be trapped in its current exoskeleton forever. It could never grow, never mature, never reproduce.\n\nWhenever you study insect development, remember: ecdysone is the switch. It tells the insect it is time to grow.",
