    correct: 3,
    explanation: "## Growing Without Changing Shape\n\nA young grasshopper looks like a small grasshopper — same shape, same features, just smaller and without wings. This is **gradual metamorphosis**.\n\nThe technical term for this pattern is *hemimetabolous development*, meaning the insect passes through a series of nymph stages that gradually resemble the adult.\n\nAt each moult, the nymph gets bigger and its wings develop a little more. There is no dramatic transformation.\n\nAphids, grasshoppers, and true bugs all develop this way. The advantage is that the nymph can live in the same habitat as the adult, eating the same food.\n\nWhenever you see a small insect that looks like a miniature version of the adult, remember: it is a nymph, not a larva. It is growing, not transforming.",
