    correct: 0,
    explanation: "## The Total Transformation\n\nA caterpillar does not look like a butterfly. A maggot does not look like a fly. This is **complete metamorphosis** — the most dramatic transformation in the animal world.\n\nThe technical term for this pattern is *holometabolous development*, and it has four distinct stages: egg, larva, pupa, and adult.\n\nThe larva (caterpillar, maggot, grub) is a feeding machine. The pupa is a transformation chamber. The adult is the reproductive stage.\n\nBecause the larva and adult live in different habitats, they do not compete for food. That is one reason this strategy has been so evolutionarily successful.\n\nWhenever you see a caterpillar turn into a butterfly, remember: you are watching the most successful developmental strategy in the animal kingdom.",
