    explanation: "## The Mouths That Chew\n\nWatch a grasshopper feeding on a blade of grass and you will see its jaws moving side to side, slicing off pieces of plant material. That is chewing.\n\nGrasshoppers and cockroaches have **chewing mouthparts** — hard mandibles that bite and grind solid food.\n\nThe technical term for these jaws is *mandibles*, and they are one of the most ancient and widespread mouthpart designs in insects.\n\nDifferent insects have different mouthparts because they eat different things. A mosquito pierces. A butterfly siphons. A housefly sponges.\n\nWhenever you study insect feeding, remember: the mouthparts tell you the diet. Chewing means solid food.",
