    explanation: "## The Needle That Feeds\n\nA mosquito lands on your arm. You do not feel it at first. Then there is a slight pinch, and a tiny tube pierces your skin and begins to draw blood.\n\nThat tube is part of a **piercing-sucking mouthpart** — a modification that allows the mosquito to access liquid food hidden inside another organism.\n\nThe technical term for this structure is *proboscis*, and it is made from elongated mouthparts that form a needle-like bundle.\n\nOther insects with this mouthpart type include bed bugs and aphids. They all feed on fluids — blood or plant sap.\n\nWhenever you study insect feeding, remember: piercing-sucking mouthparts are for getting at liquid food that would otherwise be out of reach.",
