    explanation: "## Seeing the World in Hexagons\n\nLook closely at a fly's eye and you will see something surprising: it is not one smooth surface. It is made of hundreds of tiny six-sided lenses packed together.\n\nThat is a **compound eye**, and it is the standard visual system for most adult insects.\n\nThe technical term for the individual units is *ommatidia* — each one is a separate light-sensing column that contributes a small piece of the overall image.\n\nCompound eyes are not as sharp as human eyes, but they are excellent at detecting motion. That is why it is so hard to swat a fly.\n\nWhenever you study insect vision, remember: insects do not see the world the way we do. They see it in hexagons, and they see movement faster than we can.",
