    explanation: "## Three Segments, Six Legs\n\nThe insect thorax is not one solid block. It is divided into three segments, and each one carries a pair of legs.\n\nThe three segments are the **prothorax** (front), **mesothorax** (middle), and **metathorax** (rear).\n\nThe technical term for this division is *tagmosis*, the process that groups segments into functional regions.\n\nThree segments × one pair of legs each = six legs. That simple arithmetic is why insects are called hexapods.\n\nWhenever you count insect legs, remember: they always come in three pairs, one from each thoracic segment. No exceptions.",
