    correct: 0,
    explanation: "## Breathing Through Tubes\n\nInsects do not have lungs. They do not have gills. Yet they breathe — and they do it through a system of tubes that delivers oxygen directly to every cell.\n\nThis is the **tracheal system**, and it is unique to insects and some other arthropods.\n\nThe technical term for the system is *tracheal system*, and it uses tubes called tracheae that branch into smaller tracheoles.\n\nAir enters through openings called spiracles along the sides of the body, then travels through the tubes.\n\nWhenever you study insect physiology, remember: oxygen does not travel in the blood. It travels in tubes.",
