    correct: 1,
    explanation: "## Blood That Is Not in Vessels\n\nIn humans, blood stays inside vessels. It is pumped by the heart through arteries, capillaries, and veins — never leaving the closed circuit.\n\nInsects do it differently. Their blood, called hemolymph, is pumped by a simple tube-like heart into an open body cavity called the hemocoel, where it bathes the organs directly.\n\nThe technical term for this system is *open circulatory system*, and it is much simpler than the closed system in vertebrates.\n\nHemolymph does not carry oxygen in insects — that job is done by the tracheal system.\n\nWhenever you study insect anatomy, remember: the heart is a tube, the blood is not in vessels, and the oxygen travels separately. Insects run on a completely different circulatory principle.",
