    explanation: "## The Fly That Kills Slowly\n\nTsetse flies are not like mosquitoes. They do not swarm. They do not breed in standing water. But they carry a parasite that causes one of the most feared diseases in Africa.\n\nThe disease is **sleeping sickness**, and it is caused by *Trypanosoma* parasites.\n\nThe technical term for the disease is *African trypanosomiasis*, and it affects the nervous system.\n\nTsetse flies are only found in sub-Saharan Africa, which is why sleeping sickness is confined to that region.\n\nWhenever you see a tsetse fly, remember: it looks harmless. But it carries a parasite that can kill.",
