    explanation: "## How to Tell a Butterfly From a Moth\n\nButterflies and moths look similar. Both have wings covered in tiny scales. Both feed on nectar. But there is one easy way to tell them apart: how they rest.\n\nButterflies rest with their wings **folded vertically** above their backs.\n\nThe technical term for this posture is *vertical wing folding*, and it exposes the butterfly's patterned underside — which often serves as camouflage.\n\nMoths, by contrast, rest with their wings spread flat.\n\nWhenever you see a winged insect at rest, check the wings. Vertical means butterfly. Flat means moth.",
